#include <stdio.h>

#define M 11
#define P 11

int main(void) {
    int ht[M];
    int i, kk, h0, j, c;
    int keys[] = {47, 7, 29, 11, 16, 92, 22, 8, 3};
    int k = (int)(sizeof(keys) / sizeof(keys[0]));
    int total_probe = 0, total_srch = 0;
    double asl_ins, asl_succ;
    for (i = 0; i < M; i++) ht[i] = -1;
    for (kk = 0; kk < k; kk++) {
        h0 = keys[kk] % P;
        j = h0; c = 1;
        while (ht[j] != -1) { j = (j + 1) % M; c++; }
        ht[j] = keys[kk];
        total_probe += c;
        printf("插入 %2d: h0=%2d  探测%d次  落位 %2d\n", keys[kk], h0, c, j);
    }
    asl_ins = (double)total_probe / (double)k;
    for (kk = 0; kk < k; kk++) {
        h0 = keys[kk] % P;
        j = h0; c = 1;
        while (ht[j] != -1 && ht[j] != keys[kk]) { j = (j + 1) % M; c++; }
        total_srch += c;
    }
    asl_succ = (double)total_srch / (double)k;
    printf("装填因子 alpha=%d/%d=%.3f\n", k, M, (double)k / (double)M);
    printf("平均插入探测=%.3f  查找成功 ASL=%.3f\n", asl_ins, asl_succ);
    return 0;
}
